const doc = $input.first().json.ExpenseDocuments?.[0];
const fields = {};
for (const f of (doc?.SummaryFields || [])) {
  const type = f.Type?.Text;
  const value = f.ValueDetection?.Text;
  const conf = f.ValueDetection?.Confidence;
  if (!type) continue;
  if (type === 'VENDOR_NAME') { fields.vendor = value; fields.vendorConfidence = conf; }
  if (type === 'TOTAL') { fields.amount = value; fields.amountConfidence = conf; }
  if (type === 'INVOICE_RECEIPT_DATE') { fields.date = value; }
  if (type === 'CURRENCY') { fields.currency = value; }
}
return [{ json: fields }];

const extraction = $('Extract Textract Data').first().json;
const raw = $input.first().json;
const category = (
  raw.message?.content ||
  raw.choices?.[0]?.message?.content ||
  raw.content?.[0]?.text ||
  ''
).toString().trim();
const amountNum = parseFloat((extraction.amount || '').replace(/[^0-9.]/g, ''));
const slack = $('When Slack Message Received').first().json;
const file = slack.files?.[0];
const confident = (extraction.vendorConfidence || 0) > 80 && (extraction.amountConfidence || 0) > 80 && !!amountNum;
return [{ json: {
  vendor: extraction.vendor || null,
  amount: amountNum || null,
  currency: extraction.currency || 'USD',
  date: extraction.date || null,
  category: category || 'Other',
  confident,
  slackUserId: slack.user,
  channel: slack.channel,
  fileId: file?.id || null,
  fileUrl: file?.url_private || null,
  fileName: file?.name || 'receipt.png'
}}];

