const invoice = $input.first().json;
const slack = $('When Slack Message Received').first();
return [{
  json: invoice,
  binary: slack.binary || {}
}];

const approval = $input.first().json;
const expense = $('Normalize Expense Data').first().json;
const category = String(expense.category || 'Other')
  .replace(/^["']+|[,"']+$/g, '')
  .trim();
const vendor = String(expense.vendor || 'Unknown vendor').replace(/\n/g, ' ').trim();
return [{ json: {
  ...expense,
  vendor,
  category,
  approval,
  accountCode: category === 'Travel' ? '493'
    : ['Meals', 'Client Entertainment'].includes(category) ? '420'
    : category === 'Software' ? '485'
    : category === 'Office Supplies' ? '453'
    : '429',
  route: ['Travel', 'Meals', 'Client Entertainment'].includes(category) ? 'expense' : 'bill'
}}];
